@pytest.fixture
def captured():
    assert hashlib.sha256(_CAPTURE.encode()).hexdigest() == 'b55cca41df4ee9490c537e01e77742310fc198729f9c4c7acb595da8d833a266'
    return json.loads(_CAPTURE)


def replay(captured, *, missing=False):
    bundle = bundle_from_document(captured['after'])
    entry = captured['entry']

    def boundary(source):
        if missing:
            raise CommandError('accepted boundary unavailable', kind='history_unavailable')
        assert source is entry
        return tuple(bundle_from_document(captured[key]) for key in ('before', 'after'))

    history = {source['publication_id']: source for source in [json.loads(_SOURCE_HISTORY), entry]}
    resolver = inverse_address_resolver([entry], bundle, load_boundary=boundary,
                                        load_history=history.__getitem__)
    records = select_inverse_records(AcceptedRecords(
        [entry], entry['records']['commands'], boundary), address_resolver=resolver)
    return bundle, records


def run(captured, bundle, records, intervening=()):
    request = captured['request']
    return execute(bundle, request['commands'], inverse_records=records,
                   intervening_records=intervening, commit_request=request,
                   evaluated_head=captured['head'])


def test_captured_registry_redo_preserves_exact_config_and_sources(captured):
    original = copy.deepcopy(captured)
    bundle, records = replay(captured)
    changes = coalesce(records, State(bundle))
    physical = {(write['ref'], tuple(write['path'])): write for write in changes}
    for path in (('config',), ('registry',)):
        source = next(write for write in records[0]['writes']
                      if write['ref'] == 'parent' and tuple(write['path']) == path)
        folded = physical['parent', path]
        assert folded == source
        guard(State(bundle), 'parent', list(path), folded['after'], kind='inverse_conflict')
    config = physical['parent', ('config',)]
    assert 'registry' not in config['before']['value']
    assert 'registry' not in config['after']['value']
    assert config['before']['value'] == captured['before']['parent_revision']['payload']['config']
    assert config['after']['value'] == captured['after']['parent_revision']['payload']['config']
    assert captured == original
    assert bundle == replay(captured)[0]


def test_captured_occurrence_guard_folds_same_command_aliases(captured):
    original = copy.deepcopy(captured)
    bundle, records = replay(captured)
    original_records = copy.deepcopy(list(records))
    changes = coalesce(records, State(bundle))
    aggregate = next(write for write in changes
                     if write['ref'] == 'parent' and write['path'] == ['occurrences'])
    assert aggregate['before'] == records[0]['writes'][3]['before']
    assert aggregate['after'] == present(bundle['placements'])
    assert [row['occurrence_id'] for row in aggregate['after']['value']] == ['occ-film']
    # Guard projection must retain the native alias facts for reversal and scans.
    aliases = [write for write in records[0]['writes'] if write['ref'].startswith('occurrence:')]
    assert all(write in changes for write in aliases)
    assert list(records) == original_records
    assert captured == original


def test_captured_redo_passes_canonical_occurrence_landing_guard(captured, monkeypatch):
    from astrid.sdk.timeline import inverse

    bundle, records = replay(captured)
    original = copy.deepcopy((bundle, captured, list(records)))
    passed = []

    def observe(state, ref, path, expected, **kwargs):
        guard(state, ref, path, expected, **kwargs)
        if ref == 'parent' and path == ['occurrences']:
            passed.append(copy.deepcopy(expected))

    monkeypatch.setattr(inverse, 'guard', observe)
    try:
        run(captured, bundle, records)
    except CommandError:
        # Later historical staging is a separate boundary; this assertion must
        # also hold when that continuation eventually completes the redo.
        pass
    assert passed and passed[0] == present(bundle['placements'])
    assert (bundle, captured, list(records)) == original


@pytest.mark.parametrize('mutation', ['row', 'missing', 'extra', 'duplicate',
                                     'parent-null', 'parent-empty', 'parent-rows'])
def test_captured_occurrence_landing_refuses_changed_rows(captured, mutation):
    bundle, records = replay(captured)
    if mutation == 'row':
        bundle['placements'][0]['gain'] = 0.5
    elif mutation == 'missing':
        bundle['placements'].clear()
    elif mutation.startswith('parent-'):
        bundle['parent']['occurrences'] = (None if mutation == 'parent-null' else
                                         {} if mutation == 'parent-empty' else copy.deepcopy(bundle['placements']))
    else:
        row = copy.deepcopy(bundle['placements'][0])
        if mutation == 'extra':
            row['occurrence_id'] = 'foreign-occurrence'
        bundle['placements'].append(row)
    original = copy.deepcopy((bundle, captured, list(records)))
    with pytest.raises((CommandError, ValueError)):
        run(captured, bundle, records)
    assert (bundle, captured, list(records)) == original


@pytest.mark.parametrize('mutation', ['alias-before', 'alias-owner', 'aggregate-row', 'aggregate-order',
                                     'missing-alias', 'duplicate-alias', 'absent', 'null', 'empty'])
def test_captured_occurrence_folding_refuses_contradictory_history(captured, mutation):
    writes = captured['entry']['records']['commands'][0]['writes']
    aggregate = next(write for write in writes
                     if write['ref'] == 'parent' and write['path'] == ['occurrences'])
    alias = next(write for write in writes if write['ref'].startswith('occurrence:')
                 and write['after']['state'] == 'absent')
    if mutation == 'alias-before':
        alias['before']['value']['gain'] = 0.5
    elif mutation == 'alias-owner':
        alias['before']['value']['shot_id'] = 'foreign-shot'
    elif mutation == 'aggregate-row':
        aggregate['after']['value'][0]['gain'] = 0.5
    elif mutation == 'aggregate-order':
        aggregate['after']['value'].reverse()
    elif mutation == 'missing-alias':
        writes.remove(alias)
    elif mutation == 'duplicate-alias':
        writes.append(copy.deepcopy(alias))
    elif mutation == 'absent':
        aggregate['after'] = {'state': 'absent'}
    else:
        aggregate['after'] = present(None if mutation == 'null' else {})
    original = copy.deepcopy(captured)
    with pytest.raises((CommandError, ValueError)):
        bundle, records = replay(captured)
        saved = copy.deepcopy(bundle)
        try:
            run(captured, bundle, records)
        finally:
            assert bundle == saved
    assert captured == original


@pytest.mark.parametrize('mutation', ['publication', 'step', 'negative-ordinal', 'extra-ordinal',
                                     'native-range', 'effect-range'])
def test_captured_occurrence_folding_requires_exact_source_partition(captured, mutation):
    stage = next(binding['boundary'] for binding in captured['entry']['records']['commands'][0]['bindings']
                 if binding['key'] == 'inverse.stage')
    if mutation == 'publication':
        stage['publication_id'] = 'foreign-publication'
    elif mutation == 'step':
        stage['step_id'] = 'foreign-step'
    elif mutation == 'negative-ordinal':
        stage['command_ordinals'] = [-1]
    elif mutation == 'extra-ordinal':
        stage['command_ordinals'].append(1)
    else:
        stage['native_write_range' if mutation == 'native-range' else 'effect_range'][1] -= 1
    original = copy.deepcopy(captured)
    with pytest.raises((CommandError, ValueError)):
        replay(captured)
    assert captured == original


@pytest.mark.parametrize('accepted', [False, True])
def test_captured_occurrence_folding_requires_physical_resolver(captured, accepted):
    bundle, records = replay(captured)
    unbound = (AcceptedRecords(records.entries, list(records), records.load_boundary)
               if accepted else list(records))
    changes = coalesce(unbound, State(bundle))
    aggregate = next(write for write in changes
                     if write['ref'] == 'parent' and write['path'] == ['occurrences'])
    assert aggregate == records[0]['writes'][3]
    assert len(aggregate['after']['value']) == 3


@pytest.mark.parametrize('mutation', ['empty-mirror', 'null-mirror', 'config', 'registry', 'owner'])
def test_captured_registry_redo_refuses_changed_head_without_writes(captured, mutation):
    bundle, records = replay(captured)
    if mutation == 'empty-mirror':
        bundle['parent']['config']['registry'] = {}
    elif mutation == 'null-mirror':
        bundle['parent']['config']['registry'] = None
    elif mutation == 'config':
        bundle['parent']['config']['tracks'][0]['kind'] = 'audio'
    elif mutation == 'registry':
        bundle['parent']['registry']['foreign'] = True
    else:
        bundle['placements'][0]['shot_id'] = 'foreign-shot'
    original = copy.deepcopy((bundle, captured))
    if mutation == 'owner':
        with pytest.raises((CommandError, ValueError)):
            run(captured, bundle, records)
    else:
        changes = coalesce(records, State(bundle))
        path = ['registry'] if mutation == 'registry' else ['config']
        folded = next(write for write in changes if write['ref'] == 'parent' and write['path'] == path)
        with pytest.raises(CommandError, match='original authored guard changed'):
            guard(State(bundle), 'parent', path, folded['after'], kind='inverse_conflict')
    assert (bundle, captured) == original


@pytest.mark.parametrize('mutation', ['missing', 'foreign-stage', 'digest', 'effect'])
def test_captured_registry_redo_refuses_untrusted_source(captured, mutation):
    if mutation == 'effect':
        captured['entry']['records']['steps'][0]['patch'][0]['value']['audio'] = ['foreign-effect']
    elif mutation == 'foreign-stage':
        stage = next(binding for binding in captured['entry']['records']['commands'][0]['bindings']
                     if binding['key'] == 'inverse.stage')
        stage['boundary']['publication_id'] = 'foreign-publication'
    elif mutation == 'digest':
        captured['before']['parent_revision']['content_digest'] = 'sha256:' + '0' * 64
    original = copy.deepcopy(captured)
    with pytest.raises((CommandError, ValueError)):
        _, records = replay(captured, missing=mutation == 'missing')
        list(inverse_stages(records))
    assert captured == original


def test_captured_registry_redo_refuses_intervening_aba(captured):
    bundle, records = replay(captured)
    write = records[0]['writes'][0]
    middle = copy.deepcopy(write['after'])
    middle['value']['foreign'] = True
    intervening = [{'writes': [{**write, 'before': write['after'], 'after': middle}]},
                   {'writes': [{**write, 'before': middle, 'after': write['after']}]}]
    original = copy.deepcopy((bundle, captured, intervening))
    with pytest.raises(CommandError, match='intervening publication'):
        run(captured, bundle, records, intervening)
    assert (bundle, captured, intervening) == original


@pytest.mark.parametrize('mirror', ['absent', 'empty', 'null', 'existing'])
@pytest.mark.parametrize('reverse', [False, True])
def test_physical_registry_folding_keeps_authored_mirror_presence(captured, mirror, reverse):
    # Exercise storage folding directly; these topology variants are not accepted history.
    config = copy.deepcopy(captured['after']['parent_revision']['payload']['config'])
    if mirror != 'absent':
        config['registry'] = {'assets': {}} if mirror == 'existing' else (None if mirror == 'null' else {})
    writes = [{'ref': 'parent', 'path': ['config'], 'before': present(config), 'after': present(config)},
              {'ref': 'parent', 'path': ['registry'], 'before': present({}), 'after': present({})}]
    if reverse:
        writes.reverse()
    records = [{'writes': writes}]
    original = copy.deepcopy(records)
    assert coalesce(records) == writes
    assert records == original


def test_captured_redo_restores_exact_canonical_document_and_records(captured, monkeypatch):
    from astrid.sdk.timeline import inverse
    from astrid.sdk.timeline._doc_patch import inverse_changes
    from astrid.sdk.timeline.commit import document_from_bundle

    bundle, records = replay(captured)
    original = copy.deepcopy((bundle, captured, list(records)))
    aggregates = []

    def observe(state, ref, path, expected, **kwargs):
        guard(state, ref, path, expected, **kwargs)
        if ref == 'parent' and path == ['occurrences']:
            assert state.get(ref, path) == present(state.bundle['placements'])
            aggregates.append(copy.deepcopy(expected))

    monkeypatch.setattr(inverse, 'guard', observe)
    plan = run(captured, bundle, records)
    assert aggregates[0] == present(bundle['placements'])
    assert aggregates[1] == records[0]['writes'][3]['after']
    assert len(aggregates[1]['value']) == 3
    assert 'occurrences' not in plan.bundle['parent']
    assert document_from_bundle(plan.bundle, inverse_records=records) == captured['before']
    assert plan.records[0]['writes'] == [
        {**write, 'before': write['after'], 'after': write['before']}
        for write in reversed(records[0]['writes'])]
    aggregate_read = {'ref': 'parent', 'path': ['occurrences'], 'state': present(bundle['placements'])}
    assert aggregate_read in plan.records[0]['reads']
    assert plan.steps[0]['patch'] == inverse_changes(captured['entry']['records']['steps'][0]['patch'])
    stages = [binding['boundary'] for binding in plan.records[0]['bindings']
              if binding['key'] == 'inverse.stage']
    assert stages == [{'publication_id': captured['entry']['publication_id'], 'step_id': 'inverse',
                       'command_ordinals': [0], 'native_write_range': [0, 10], 'effect_range': [0, 9]}]
    assert (bundle, captured, list(records)) == original


@pytest.mark.parametrize('mutation', ['row', 'missing', 'duplicate', 'foreign-id', 'foreign-owner',
                                     'order', 'absent', 'null', 'object', 'pin'])
def test_captured_redo_refuses_changed_historical_aggregate(captured, mutation):
    aggregate = captured['entry']['records']['commands'][0]['writes'][3]
    rows = aggregate['before']['value']
    if mutation == 'row':
        rows[0]['gain'] = 0.5
    elif mutation == 'missing':
        rows.pop()
    elif mutation == 'duplicate':
        rows.append(copy.deepcopy(rows[0]))
    elif mutation == 'foreign-id':
        rows[0]['occurrence_id'] = 'foreign-occurrence'
    elif mutation == 'foreign-owner':
        rows[0]['shot_id'] = 'foreign-shot'
    elif mutation == 'order':
        rows.reverse()
    elif mutation == 'absent':
        aggregate['before'] = {'state': 'absent'}
    elif mutation in ('null', 'object'):
        aggregate['before'] = present(None if mutation == 'null' else {})
    else:
        rows[0]['shot_revision_id'] = 'forged-revision'
    original = copy.deepcopy(captured)
    with pytest.raises((CommandError, ValueError)):
        bundle, records = replay(captured)
        saved = copy.deepcopy(bundle)
        try:
            run(captured, bundle, records)
        finally:
            assert bundle == saved
    assert captured == original


@pytest.mark.parametrize('mutation', ['row', 'missing', 'duplicate', 'foreign-id', 'foreign-owner', 'order'])
def test_captured_historical_guard_checks_physical_rows(captured, mutation, monkeypatch):
    from astrid.sdk.timeline import inverse

    bundle, records = replay(captured)
    original = copy.deepcopy((bundle, captured, list(records)))
    reached = []

    def tamper(state, ref, path, expected, **kwargs):
        if ref == 'parent' and path == ['occurrences'] and len(expected['value']) == 3:
            reached.append(True)
            rows = state.bundle['placements']
            assert present(rows) == expected
            if mutation == 'row':
                rows[0]['gain'] = 0.5
            elif mutation == 'missing':
                rows.pop()
            elif mutation == 'duplicate':
                rows.append(copy.deepcopy(rows[0]))
            elif mutation == 'foreign-id':
                rows[0]['occurrence_id'] = 'foreign-occurrence'
            elif mutation == 'foreign-owner':
                rows[0]['shot_id'] = 'foreign-shot'
            else:
                rows.reverse()
        guard(state, ref, path, expected, **kwargs)

    monkeypatch.setattr(inverse, 'guard', tamper)
    with pytest.raises(CommandError, match='original authored guard changed') as failure:
        run(captured, bundle, records)
    assert reached == [True]
    assert failure.value.ref == 'parent'
    assert failure.value.path == ['occurrences']
    assert (bundle, captured, list(records)) == original
